  '@media (max-width:900px){.mp-eqwin-layer{padding:12px}.mp-eqwin{width:100%;height:100%}.mp-eqwin-head{padding:12px 16px}.mp-eqwin-body{padding:12px 16px 16px;gap:12px}}',
